using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
public static class FitPhoneLeafletGrips { public static object Main(){if(EditorApplication.isPlayingOrWillChangePlaymode)throw new Exception("Edit required");const string scene="Assets/ShooterSurvival/Scenes/Tools/Jamsil.unity";EditorSceneManager.OpenScene(scene);File.Copy(scene,"outputs/chapter45-detailed-design-2026-10-03/scene-recovery/Jamsil-before-readable-phone-cards-v2.unity",false);int phones=0,cards=0;foreach(var b in UnityEngine.Object.FindObjectsByType<Chapter45HandProps>(FindObjectsInactive.Include,FindObjectsSortMode.None)){var role=b.GetComponentInParent<Chapter45RoleAction>(true);if(role==null)continue;if(role.role==Chapter45RoleAction.Role.PhoneShopper){b.useLeftHand=true;b.style=Chapter45HandProps.Style.Phone;phones++;}else if(role.role==Chapter45RoleAction.Role.Promoter){b.useLeftHand=true;b.style=Chapter45HandProps.Style.Leaflets;cards++;}else continue;b.ApplyPose();EditorUtility.SetDirty(b);}var s=UnityEngine.SceneManagement.SceneManager.GetActiveScene();EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);return new{phones,cards,collidersChanged=0,source="Existing native functional props; palm position and readable orientation corrected."};}}
